<?php
namespace davvag_credit_points;
require_once __DIR__ . "/CreditLedgerService.php";
class CreditCouponService {
    private $ledger;
    public function __construct($ledger=null){$this->ledger=$ledger?:new CreditLedgerService();}
    private function pepper(){$value=getenv("DAVVAG_CREDIT_COUPON_PEPPER");$value=$value===false?"":trim($value);if(strlen($value)<32)throw new CreditException("Coupon security is not configured.");return$value;}
    private function hashCode($code){return hash_hmac("sha256",CreditRules::normalizeCoupon($code),$this->pepper());}
    public function generate($campaignId,$count,$maximumRedemptions=1,$assignedProfileId=0,$expiresAt=null){$count=max(1,min(500,intval($count)));$maximumRedemptions=max(1,intval($maximumRedemptions));$db=$this->ledger->database();$campaign=$db->one("SELECT * FROM davvag_credit_coupon_campaign WHERE id=? LIMIT 1","i",array(intval($campaignId)));if(!$campaign)throw new CreditException("Coupon campaign was not found.");$codes=array();$db->transaction(function($txdb)use($campaign,$count,$maximumRedemptions,$assignedProfileId,$expiresAt,&$codes){for($index=0;$index<$count;$index++){$plain="DV-".strtoupper(bin2hex(random_bytes(4)))."-".strtoupper(bin2hex(random_bytes(4)));$normalized=CreditRules::normalizeCoupon($plain);$txdb->insert("davvag_credit_coupon_code",array("campaign_id"=>intval($campaign->id),"code_hash"=>$this->hashCode($normalized),"masked_code"=>substr($normalized,0,4)."********".substr($normalized,-4),"assigned_profile_id"=>intval($assignedProfileId),"maximum_redemptions"=>$maximumRedemptions,"redemption_count"=>0,"expires_at"=>$expiresAt,"status"=>"ACTIVE"));$codes[]=$plain;}});return$codes;}
    public function redeem($profileId,$code,$idempotencyKey,$actor=array()){$normalized=CreditRules::normalizeCoupon($code);if(strlen($normalized)<12)throw new CreditException("The coupon could not be redeemed.");$db=$this->ledger->database();$coupon=$db->one("SELECT c.*,m.program_id,m.name campaign_name,m.credit_amount,m.total_redemption_limit,m.per_profile_limit,m.active_from,m.active_until,m.credit_expiry_days,m.status campaign_status,p.code program_code,p.coupon_available FROM davvag_credit_coupon_code c JOIN davvag_credit_coupon_campaign m ON m.id=c.campaign_id JOIN davvag_credit_program p ON p.id=m.program_id WHERE c.code_hash=? LIMIT 1","s",array($this->hashCode($normalized)));if(!$coupon||$coupon->status!=="ACTIVE"||$coupon->campaign_status!=="ACTIVE"||!CreditRules::truthy($coupon->coupon_available))throw new CreditException("The coupon could not be redeemed.");$now=time();if(!empty($coupon->expires_at)&&strtotime($coupon->expires_at)<$now||!empty($coupon->active_from)&&strtotime($coupon->active_from)>$now||!empty($coupon->active_until)&&strtotime($coupon->active_until)<$now)throw new CreditException("The coupon could not be redeemed.");if(intval($coupon->assigned_profile_id)>0&&intval($coupon->assigned_profile_id)!==intval($profileId))throw new CreditException("The coupon could not be redeemed.");$expires=intval($coupon->credit_expiry_days)>0?date("Y-m-d H:i:s",time()+intval($coupon->credit_expiry_days)*86400):null;$context=array("programCode"=>$coupon->program_code,"sourceApp"=>"davvag-credit-points","referenceType"=>"coupon-redemption","referenceId"=>strval($coupon->id),"idempotencyKey"=>CreditRules::idempotency($idempotencyKey),"description"=>"Redeem gift credit coupon","metadata"=>array("campaignId"=>intval($coupon->campaign_id),"couponCodeId"=>intval($coupon->id)),"actorProfileId"=>intval(isset($actor["profileId"])?$actor["profileId"]:$profileId),"actorUserId"=>isset($actor["userId"])?$actor["userId"]:"");return$this->ledger->credit($profileId,$coupon->credit_amount,$context,"COUPON_GIFT",$expires,false,function($txdb,$tx)use($coupon,$profileId,$idempotencyKey){$locked=$txdb->one("SELECT * FROM davvag_credit_coupon_code WHERE id=? FOR UPDATE","i",array($coupon->id));$campaign=$txdb->one("SELECT * FROM davvag_credit_coupon_campaign WHERE id=? FOR UPDATE","i",array($coupon->campaign_id));if(!$locked||$locked->status!=="ACTIVE"||intval($locked->redemption_count)>=intval($locked->maximum_redemptions))throw new CreditException("The coupon could not be redeemed.");$profileCount=$txdb->one("SELECT COUNT(*) amount FROM davvag_credit_coupon_redemption WHERE campaign_id=? AND profile_id=?","ii",array($campaign->id,intval($profileId)));if(intval($campaign->per_profile_limit)>0&&intval($profileCount->amount)>=intval($campaign->per_profile_limit))throw new CreditException("The coupon could not be redeemed.");$total=$txdb->one("SELECT COUNT(*) amount FROM davvag_credit_coupon_redemption WHERE campaign_id=?","i",array($campaign->id));if(intval($campaign->total_redemption_limit)>0&&intval($total->amount)>=intval($campaign->total_redemption_limit))throw new CreditException("The coupon could not be redeemed.");$txdb->insert("davvag_credit_coupon_redemption",array("campaign_id"=>intval($campaign->id),"coupon_code_id"=>intval($locked->id),"profile_id"=>intval($profileId),"period_or_limit_key"=>"PROFILE:".intval($profileId),"idempotency_key"=>$idempotencyKey,"transaction_id"=>intval($tx->id),"redeemed_at"=>date("Y-m-d H:i:s")));$txdb->updateById("davvag_credit_coupon_code",$locked->id,array("redemption_count"=>intval($locked->redemption_count)+1,"status"=>intval($locked->redemption_count)+1>=intval($locked->maximum_redemptions)?"REDEEMED":"ACTIVE"));});}
}
?>
